import numpy as np

# Prove RRF consensus boost & exact scale invariance vs fragile raw score addition
bm25_scores  = {'DocA': 24.5, 'DocC': 21.0, 'DocB': 4.2,  'DocD': 1.1}
dense_scores = {'DocB': 0.86, 'DocC': 0.84, 'DocA': 0.62, 'DocD': 0.55}

def to_ranks(score_dict):
    ordered = sorted(score_dict.items(), key=lambda x: -x[1])
    return {doc: idx + 1 for idx, (doc, _) in enumerate(ordered)}

def rrf(rank_lists, k=60):
    docs = set().union(*[r.keys() for r in rank_lists])
    return {d: sum(1.0 / (k + r.get(d, 1000)) for r in rank_lists) for d in docs}

r_bm25, r_dense = to_ranks(bm25_scores), to_ranks(dense_scores)
# Override ranks to match exact concrete example: A(1,12), B(15,1), C(2,2)
rrf_ex = rrf([{'DocA': 1, 'DocC': 2, 'DocB': 15}, {'DocB': 1, 'DocC': 2, 'DocA': 12}], k=60)
winner = max(rrf_ex, key=rrf_ex.get)
assert winner == 'DocC' and rrf_ex['DocC'] > rrf_ex['DocA'] > rrf_ex['DocB']
# Scale invariance test: multiply BM25 by 100x -> RRF ranks unchanged!
scaled_bm25 = {d: v * 100.0 for d, v in bm25_scores.items()}
assert rrf([to_ranks(bm25_scores), r_dense]) == rrf([to_ranks(scaled_bm25), r_dense])
print('RRF Example Scores:', {k: round(v, 5) for k, v in sorted(rrf_ex.items(), key=lambda x: -x[1])})
print('Winner:', winner, '| Verified 100% scale-invariant!')

import hashlib

# Prove double-charge bug on timeout-after-commit vs exact-once safety with Idempotency Key
class PaymentAPI:
    def __init__(self, balance=1000):
        self.balance, self.tx_seq, self.dedup = balance, 0, {}
    def charge(self, amount, idem_key=None, drop_first_ack=False):
        if idem_key and idem_key in self.dedup:
            return self.dedup[idem_key]  # Safe cached receipt, zero duplicate debit!
        self.tx_seq += 1
        self.balance -= amount
        receipt = {'tx_id': f'tx_{self.tx_seq}', 'amount': amount, 'status': 'ok'}
        if idem_key:
            self.dedup[idem_key] = receipt
        if drop_first_ack and self.tx_seq == 1:
            raise TimeoutError('Network timeout AFTER server commit!')
        return receipt

# 1) Without Idempotency Key -> Double Charge!
api_unsafe = PaymentAPI(1000)
try: api_unsafe.charge(500, idem_key=None, drop_first_ack=True)
except TimeoutError: r_unsafe = api_unsafe.charge(500, idem_key=None)

# 2) With Deterministic Idempotency Key -> Charged Exactly Once!
api_safe = PaymentAPI(1000)
key = hashlib.sha256(b'run_88:slot_2:order_901').hexdigest()[:16]
try: api_safe.charge(500, idem_key=key, drop_first_ack=True)
except TimeoutError: r_safe = api_safe.charge(500, idem_key=key)

assert api_unsafe.balance == 0 and api_safe.balance == 500 and r_safe['tx_id'] == 'tx_1'
print(f'Unsafe retry balance: ${api_unsafe.balance} (DOUBLE CHARGED!) | Safe Idempotent balance: ${api_safe.balance} ({r_safe})')
